function widestRamp(nums: number[]): number {
  let best = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = nums.length - 1; j > i + best; j--) {
      if (nums[i] <= nums[j]) { best = j - i; break; }
    }
  }
  return best;
}

