function widestRamp(nums: number[]): number {
  const idx = nums.map((_, i) => i).sort((a, b) => nums[a] - nums[b] || a - b);
  let best = 0, minIdx = Infinity;
  for (const j of idx) {
    best = Math.max(best, j - minIdx);
    minIdx = Math.min(minIdx, j);
  }
  return best;
}

