function widestRamp(nums: number[]): number {
  const stack: number[] = [];
  for (let i = 0; i < nums.length; i++) {
    if (!stack.length || nums[i] < nums[stack[stack.length - 1]]) stack.push(i);
  }
  let best = 0;
  for (let j = nums.length - 1; j >= 0 && stack.length; j--) {
    while (stack.length && nums[stack[stack.length - 1]] <= nums[j]) {
      best = Math.max(best, j - stack.pop()!);
    }
  }
  return best;
}

